import json,os,numpy as np
F=json.load(open('results/final.json'));G=json.load(open('results/diagnostics_final.json'));os.makedirs('models',exist_ok=True)
units={'a':'bar/(s*(l/min))','b':'bar/s','c':'-','r':'1/s','n':'-','m':'-','pa':'bar'}
def num(v):return format(float(v),'.12g')
def kv(name,value,unit,typ,desc,equation=None):
 d={'name':name,'value':float(value),'unit':unit,'type':typ,'description':desc}
 if equation is not None:d['equation']=equation
 return d
bases={
 'MixedResistance':{'family':'Lumped isothermal gas-inventory balance with mixed linear/quadratic hydraulic resistance. The discharge is the positive root of a quadratic pressure-loss relation, regularized at zero pressure drop.', 'origin':'The inlet-minus-outlet balance and square-root high-pressure behavior came from gas storage and restriction-flow reasoning. A linear-pressure model was tried first and rejected for flow-dependent pressure bias. Regularized orifice and generalized-pressure-power models improved it. Residual low-pressure bias motivated the inverse-quadratic loss relation, rather than adding an unexplained constant source. The rational-power valve map was a manually proposed monotone saturation law, not a symbolic-regression discovery. The near-atmospheric reference is estimated because recorded low-flow pressures can lie below the nominal atmospheric value.','ph':'(sqrt((Max(p-pa,0)+s)/pr)-sqrt(s/pr))','detail':'The outlet term `b*x**m/(1+c*x**m)*(sqrt((Max(p-pa,0)+s)/pr)-sqrt(s/pr))` approaches a linear pressure-drop law near atmosphere and a square-root law at larger pressure drops. It is the positive solution of a mixed linear/quadratic resistance relation, with coefficients absorbed into `b` and `s`.','extra':'The fitted `pa` reaches its lower bound; this is evidence of confounding between low-pressure discharge shape and the empirical atmospheric reference, not an independent atmospheric-pressure measurement.'},
 'RegularizedOrifice':{'family':'Lumped isothermal gas-inventory balance with a regularized turbulent-orifice outlet and a power-law valve characteristic.','origin':'The linear mass-flow source, zero pressure-drop discharge and sealed-valve endpoint came from physical reasoning. The square-root large-drop behavior was chosen as a turbulent-restriction hypothesis. The pressure regularization and power-aperture valve map were manually proposed, not generated by symbolic regression. Linear pressure relaxation and saturation alternatives were tested before retaining this compact fixed-exponent comparison.','ph':'(Max(p-pa,0)/pr)/sqrt((Max(p-pa,0)+s)/pr)','detail':'The outlet term `b*x**m*(Max(p-pa,0)/pr)/sqrt((Max(p-pa,0)+s)/pr)` is linear near atmosphere and approaches square-root pressure-drop scaling away from atmosphere. It is a smooth approximation to an orifice law, not an exact compressible nozzle equation.','extra':'This is deliberately the simplest retained turbulent model and has higher pressure RMSE than the recommended candidate. The fixed atmospheric reference avoids estimating an offset that is confounded with pressure regularization.'},
 'GeneralizedDischarge':{'family':'Grey-box lumped isothermal gas-inventory balance with a generalized regularized pressure-power discharge and a monotone rational-power valve characteristic.','origin':'Gas inventory reasoning supplied the inlet-minus-outlet balance, atmospheric equilibrium and sealed endpoint. A linear-pressure baseline had substantial flow-dependent residual bias. Regularized square-root discharge reduced it; residual low-pressure bias motivated an adjustable exponent and atmospheric reference. The rational-power valve characteristic was manually proposed after testing exponential, power and saturating conductances. The exponent is a phenomenological relaxation of the square-root hypothesis, not a newly inferred physical law. Symbolic regression and sparse polynomial regression were considered but not run: the constrained balance families supplied the required signs directly.','ph':'(Max(p-pa,0)/pr)*((Max(p-pa,0)+s)/pr)**(n-1)','detail':'The outlet term `b*x**m/(1+c*x**m)*(Max(p-pa,0)/pr)*((Max(p-pa,0)+s)/pr)**(n-1)` is linear at very small pressure drop and approaches a pressure-power relation with exponent `n` at larger drops. The fitted exponent is near square-root behavior. It represents effective restriction scaling, not a uniquely identified flow regime.','extra':'The adjustable exponent, regularizer, inlet coefficient and atmospheric reference are correlated; their numerical values do not uniquely determine geometry or headspace volume. This candidate is preferred for compactness and train-only validation performance, not because it removes the observed nonstationarity.'},
 'CompressibleDischarge':{'family':'Lumped isothermal gas-inventory balance with a regularized pressure-squared gas-restriction outlet. This is a compressibility-sensitive resistance approximation, not a choked-flow nozzle model.','origin':'The gas balance and monotonic valve endpoint constraints came from physical reasoning. A density correction using pressure-squared difference was tried after the square-root models left pressure-dependent residuals. The factor involving absolute pressure was an assumed isothermal resistance correction, not a term selected by symbolic search. The rational-power aperture characteristic was retained from the manually tested valve families to isolate this pressure-law alternative.','ph':'(Max(p-pa,0)/pr)*sqrt(Max(p+pa,0)/(2*pa))/sqrt((Max(p-pa,0)+s)/pr)','detail':'The outlet term `b*x**m/(1+c*x**m)*(Max(p-pa,0)/pr)*sqrt(Max(p+pa,0)/(2*pa))/sqrt((Max(p-pa,0)+s)/pr)` becomes proportional to the square root of a pressure-squared difference away from the small-drop regularization. The absolute-pressure factor models density sensitivity while preserving zero discharge at the reference pressure.','extra':'This approximation does not include choking or gas-temperature dynamics. Its training and train-only validation errors were worse than the generalized-discharge model. The fitted atmospheric reference reaches its lower bound, so neither its offset nor the assumed compressibility correction is established independently by these experiments.'},
 'TabulatedValve':{'family':'Grey-box lumped isothermal gas-inventory balance with a monotone continuous piecewise-linear valve characteristic and generalized regularized pressure-power discharge.','origin':'Physical reasoning supplied the inlet source, nonnegative pressure-driven outlet, atmospheric equilibrium and sealed endpoint. Smooth parametric valve laws were tried first. Valve-binned residuals motivated a monotone tabulated characteristic to test whether a restricted analytic valve curve was causing errors. Knot locations were chosen before this fit to resolve the high-closure regime more finely, where training pressure is most sensitive to the valve. Positive increments were imposed rather than estimating unrestricted coefficients. The worse train-only validation error cautions against overinterpreting the extra flexibility.','ph':'(Max(p-pa,0)/pr)*((Max(p-pa,0)+s)/pr)**(n-1)','detail':'The outlet term is the product of the monotone ramp sum and `h*(h+s/pr)**(n-1)`. Each ramp adds a nonnegative increment to conductance over one aperture interval, giving a measured-valve calibration curve without oscillatory polynomial extrapolation.','extra':'The extreme-open and near-sealed segments are weakly excited. The knot schedule is assumed, not inferred valve geometry. Its final validation-trajectory error is slightly smaller after joint refitting, but its worse truly held-out validation result makes it less compelling than the compact recommendation.'}}
for label,B in bases.items():
 final=F[label]['final'];sel=F[label]['selection'];t=final['params'];z=final['rhs_params'];rows=[]
 rows.append(kv('vscale',100.,'%', 'fixed','Full-closure position `vscale = 100` %, supplied by TASK.md; normalizes aperture and fixes the sealed endpoint.'))
 rows.append(kv('pr',1.,'bar','fixed','Pressure normalization `pr = 1` bar, chosen to nondimensionalize pressure powers without changing the numerical bar-valued fits.'))
 if label=='TabulatedValve':
  vals=dict(zip(['a','r','n','pa','dA','dB','dC','dD','dE','dF'],t));idx=list(vals)
  for name,value in vals.items():
   unit='bar/s' if name.startswith('d') else units[name]
   desc={'a':'Positive inlet pressure gain per recorded air-flow rate.','r':'Maximum fully-open near-atmospheric relaxation rate; bounded for five-second RK4 stability.','n':'Large-pressure-drop discharge exponent.','pa':'Empirical atmospheric-equilibrium reference, allowed a small offset from nominal one bar.'}.get(name,'Nonnegative conductance increment in the corresponding aperture interval; fitted jointly with all other independent parameters.')
   rows.append(kv(name,value,unit,'fitted',desc))
  knot_names=['kA','kB','kC','kD','kE'];kn=[.10,.20,.30,.45,.65]
  for name,value in zip(knot_names,kn):rows.append(kv(name,value,'-','fixed','Assumed dimensionless aperture knot, chosen to place more resolution at high closure; not estimated from either trajectory.'))
  x='Min(Max((vscale-valve)/vscale,0),1)';cv=[];prev='0';nexts=knot_names+['1'];ds=['dA','dB','dC','dD','dE','dF']
  for d,kk in zip(ds,nexts):cv.append(f'{d}*Min(Max(({x}-{prev})/({kk}-{prev}),0),1)');prev=kk
  conductance='('+'+'.join(cv)+')'
  eq='pr*((dA+dB+dC+dD+dE+dF)/(r*pr))**(1/(1-n))'
  rows.append(kv('s',z[1],'bar','tied','Small-pressure regularization scale determined by the fully-open conductance and fitted relaxation rate.',eq))
  expression='a*Max(flow,0)-'+conductance+'*'+B['ph']+'+r*Max(pa-p,0)'
  independent=['a','r','n','pa','dA','dB','dC','dD','dE','dF'];initial=sel['start'];trainini=sel['initial'];jointini=final['initial']
  bounds='`0.0002 <= a <= 0.004` bar/(s*(l/min)), `0.03 <= r <= 0.5` 1/s, `0.3 <= n <= 0.85`, `0.98 <= pa <= 1.02` bar, and `0.000001 <= dA <= 0.15` bar/s with the same bounds on `dB`, `dC`, `dD`, `dE`, `dF`'
  startnames=independent
 else:
  names=['a','b','c','r','n','m','pa','unused'];independent=[names[i] for i in final['idx']];vals=dict(zip(names,t));
  desc={'a':'Positive pressure-rate gain per air-flow rate, estimated from the logged standard-volume flow.','b':'Outlet pressure-rate scale before the aperture and pressure factors.','c':'Nonnegative saturation parameter of the rational-power valve characteristic.','r':'Fully-open near-atmospheric relaxation rate, bounded to preserve five-second RK4 stability.','n':'Phenomenological large-drop exponent of the generalized pressure discharge.','m':'Positive exponent controlling the aperture characteristic.','pa':'Empirical near-atmospheric equilibrium reference; not an independently measured ambient pressure.'}
  for name in independent:rows.append(kv(name,vals[name],units[name],'fitted',desc[name]))
  if 'pa' not in independent:rows.append(kv('pa',t[6],'bar','fixed','Nominal atmospheric pressure `pa = 1` bar from TASK.md, held fixed to avoid an extra uncertain offset.'))
  x='Min(Max((vscale-valve)/vscale,0),1)'
  conductance='b*'+x+'**m' if label=='RegularizedOrifice' else 'b*'+x+'**m/(1+c*'+x+'**m)'
  if label=='MixedResistance':eq='pr*(b/((1+c)*2*r*pr))**2'
  elif label=='CompressibleDischarge':eq='pr*(b/((1+c)*r*pr))**2'
  elif label=='RegularizedOrifice':eq='pr*(b/(r*pr))**2'
  else:eq='pr*(b/((1+c)*r*pr))**(1/(1-n))'
  rows.append(kv('s',z[3],'bar','tied','Pressure regularization chosen by the fitted fully-open atmospheric relaxation rate, not an additional independent fit.',eq))
  expression='a*Max(flow,0)-'+conductance+'*'+B['ph']+'+r*Max(pa-p,0)'
  startnames=names;initial=sel['start'];trainini=sel['initial'];jointini=final['initial']
  bounds='`0.0001 <= a <= 0.004` bar/(s*(l/min)), `0.01 <= b <= 1` bar/s, `0 <= c <= 30`, `0.03 <= r <= 0.5` 1/s, `0.3 <= n <= 0.85`, `0.5 <= m <= 3`, and `0.98 <= pa <= 1.02` bar, applying only to the independent fitted parameters of this candidate'
 def assignments(arr):
  return ', '.join('`'+name+' = '+num(arr[startnames.index(name)])+'`'+(' '+(units.get(name,'bar/s')) if units.get(name,'bar/s')!='-' else '') for name in independent)
 # Exact sequential initialization record, not generic run description.
 method='Bound-constrained nonlinear least squares with the Trust Region Reflective algorithm in `scipy.optimize.least_squares`, using SciPy 1.18.1; reference: the official SciPy documentation for this function, cited from memory; attempted web retrieval returned no usable page content. This method handles sign and stability bounds directly, unlike unconstrained Levenberg-Marquardt. All independent parameters were estimated jointly within each step; tied `s` was recomputed on every evaluation. Step one minimized derivative residuals on training rows except the final row, multiplying residuals by a fixed numerical factor of one hundred for conditioning; this does not change their least-squares minimizer. Initial values were '+assignments(initial)+'. These are hand-chosen order-of-magnitude gas-balance values, positive valve-shape values, a square-root-nearby exponent, and a near-one-bar atmospheric reference. The initial relaxation-rate guess was below the stability ceiling. Step two minimized free-running training-trajectory pressure errors from the derivative-fit solution '+assignments(trainini)+'. This train-only fit was used for structural comparison on validation. Step three jointly minimized pressure errors on both trajectories, initialized by the training simulation fit '+assignments(jointini)+'. Final bounds were '+bounds+'. The relaxation ceiling is an assumed numerical admissibility constraint, not a measured physical rate. Each derivative fit allowed eight hundred function evaluations, with `ftol = 1e-10`, `xtol = 1e-10`, `gtol = 1e-10`; each simulation fit allowed twelve hundred with corresponding tolerances `1e-11`. All used `method = \'trf\'`, `jac = \'2-point\'`, `x_scale = \'jac\'` and ordinary squared loss. No randomization or multistart was used, so no seed applies; this is a local, not certified-global, optimum. The scripts use Numba 0.68.0 only to accelerate deterministic right-hand-side and RK4 loops.'
 criterion='The final criterion is the sum of squared free-running errors on `p`, in bar squared, across both trajectories after their initial samples. Each trajectory is initialized at its first logged `p`; inputs are held at the logged sample values for a classical RK4 step of five seconds, with no measurement resets. This matches the scored simulation setting and avoids treating filtered `dp` as an exact vector field. The preliminary criterion was squared error on `dp`, in (bar/s) squared, only to obtain a starting point. No outlier removal, weighting or regularization penalty was used.'
 data='The first two estimation steps used data/train.csv: all 1452 samples as the contiguous trajectory, with 1451 derivative targets or subsequent-state pressure errors. Structural selection used data/val.csv as a separate 1454-sample trajectory, never concatenating its state to training. The final refit used both complete trajectories, for 2904 subsequent-state errors. Initial samples supply the initial states and have no fitted pressure-error term. The final row of each file is not a derivative initialization target because its successor is unavailable. No inaccessible test data were used; final validation-trajectory errors are in-sample after joint refitting.'
 common='Here `p` is measured absolute headspace pressure in bar, `valve` is percent closed and `flow` is air flow in l/min. `vscale` is full closure in %, `pr` is a one-bar pressure normalization and `pa` is the atmospheric-equilibrium reference in bar. Define the explanatory aperture `x = Min(Max((vscale-valve)/vscale,0),1)` and nonnegative dimensionless pressure drop `h = Max(p-pa,0)/pr`. The inlet term `a*Max(flow,0)` converts nonnegative supplied air flow to pressure accumulation; negative flow is clipped only as an untested domain continuation. The outlet characteristic vanishes at full closure. The final term `r*Max(pa-p,0)` restores pressure below the reference at a valve-independent bounded rate. It is a numerical/phenomenological continuation, not evidence of a physical leak.'
 if label!='TabulatedValve':
  common+=' `b` is a pressure-rate scale in bar/s, `m` is the aperture exponent, '+('and `c` is a dimensionless saturation parameter. ' if label!='RegularizedOrifice' else 'with no saturation parameter in this candidate. ')
  if label=='GeneralizedDischarge':common+='`n` is the dimensionless large-drop pressure exponent. '
 else:common+=' `dA`, `dB`, `dC`, `dD`, `dE` and `dF` are conductance increments in bar/s over aperture intervals bounded by zero, `kA`, `kB`, `kC`, `kD`, `kE` and one. `n` is the dimensionless large-drop exponent. '
 common+='`s` is a tied pressure scale in bar, and `r` is the atmospheric relaxation rate in 1/s. '+B['detail']
 R=' R1 holds globally because the inlet coefficient is positive and `Max(flow,0)` is nondecreasing. R2 holds for percent closure from zero to one hundred: conductance is nondecreasing with aperture, the discharged pressure factor is nonnegative, and the below-reference recovery term is independent of closure. Clipping extends this monotonicity beyond that input interval. R3 holds exactly at `p = pa` with `flow = 0`, for every open valve; '+('`pa = 1` bar is fixed. ' if label=='RegularizedOrifice' else 'the fitted `pa = '+num(vals['pa'])+'` bar is approximately nominal atmospheric pressure, but represents an empirical offset. ')+ 'R4 holds: above `pa` the zero-flow derivative is negative for an open valve and below `pa` it is positive. R5 holds: at `valve = vscale` the outlet is zero and supplied nonnegative flow cannot lower pressure. Above `pa`, a sealed tank reduces exactly to `a*Max(flow,0)`.'
 limitations=B['extra']+' '+R+' The valve-independent subatmospheric recovery is an intentional mathematical extension used to meet the requested global closure monotonicity. It should not be interpreted as actual air ingress through a sealed vessel. Physical use is mainly at or above the near-atmospheric reference. Constant temperature, constant effective gas capacitance, input alignment and instantaneous actuator response are assumed. Neither temperature, actual gas inventory, bubble holdup, valve hysteresis nor sensor calibration is measured here. The fitted inlet gain folds these effects into one coefficient. The pressure and input ranges of the two supplied experiments do not identify behavior at much higher pressure or at exact full closure; no relief valve is modeled. Long sealed operation with continuing inlet can physically exceed the harness pressure bound; no artificial pressure cap was added because it would contradict the sealed accumulation law. Sign constraints and the imposed atmospheric relaxation bound prevent local zero-flow numerical instability, but do not certify arbitrary high-pressure trajectories. '
 stats='For this candidate, the train-only free-running fit had training RMSE `'+num(sel['train_rmse'])+'` bar and genuinely held-out validation RMSE `'+num(sel['val_rmse'])+'` bar. After joint refitting, training-trajectory RMSE was `'+num(final['train_rmse'])+'` bar and validation-trajectory RMSE was `'+num(final['val_rmse'])+'` bar; these last two are in-sample diagnostics, not test results. Simulation residuals were inspected by pressure, valve, flow and time quintiles. Final residual lag-one correlations were `'+num(G[label]['train']['residual_lag_one_corr'])+'` on training and `'+num(G[label]['val']['residual_lag_one_corr'])+'` on validation. Sustained time-dependent errors remain, so omitted memory or changing operating conditions are plausible but not identifiable from the permitted one-state model. No time-dependent corrective term was inserted.'
 B['origin']+=' The regularizer was parameterized through the fitted fully-open atmospheric relaxation rate after unconstrained exploratory fits showed that some low-drop slopes would be unsafe for a five-second explicit RK4 step. This is an intentional simulation-safety restriction, not evidence for a particular laminar transition. '+stats
 family=B['family']+' The common gas-inventory motivation is the ideal-gas equation of state at fixed effective volume and temperature; reference: NASA Glenn Research Center, Equation of State, cited from memory and not source-checked; attempted web retrieval returned no usable page content. The particular valve map and regularization are assumptions of this identification, not formulas supplied by that reference.'
 model={'expressions':{'dp':expression},'parameters':rows,'estimation':{'criterion':criterion,'data':data,'method':method,'script':'fit_final.py'},'discussion':{'family':family,'interpretation':common,'origin':B['origin'],'limitations':limitations}}
 json.dump(model,open('models/'+label+'.json','w'),indent=2)
pool={'order':['GeneralizedDischarge','MixedResistance','TabulatedValve','CompressibleDischarge','RegularizedOrifice'],'recommended':'GeneralizedDischarge','reason':'The compact generalized gas-balance model achieved the lowest genuinely held-out validation RMSE among the final stable candidate structures: `0.0386073098819` bar from a train-only fit. Its final parameters are jointly refitted on the training and validation trajectories; their pressure RMSE values are `0.0245809178926` bar and `0.0372737413879` bar, respectively, and are therefore in-sample rather than held-out. The tabulated valve model has a slightly lower final joint-data error but had worse train-only validation performance and greater calibration flexibility. The recommendation preserves positive inlet response, monotone valve response, near-atmospheric recovery, and exact sealed-valve accumulation above the atmospheric reference. The square-root-nearby discharge exponent is an interpretable effective restriction law; systematic time-dependent residuals remain, so no test-performance claim is made.'}
json.dump(pool,open('models/pool.json','w'),indent=2)
